using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Documents.Api.Data;using Documents.Api.Models;using Documents.Api.Services;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;
var b=WebApplication.CreateBuilder(args);var secret=b.Configuration["Jwt:Secret"]??"development-only-secret-change-me-32-characters";b.Services.AddDbContext<DocumentsDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("Default")??"Data Source=documents.db"));b.Services.AddScoped<IPasswordHasher<User>,PasswordHasher<User>>();b.Services.AddScoped<DocumentService>();b.Services.AddOpenApi();b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret))});b.Services.AddAuthorization();var app=b.Build();app.UseExceptionHandler("/error");app.UseAuthentication();app.UseAuthorization();if(app.Environment.IsDevelopment())app.MapOpenApi();app.Map("/error",()=>Results.Json(new{error=new{code="SERVER_ERROR",message="Request could not be completed"}},statusCode:500));
app.MapPost("/api/auth/login",async(Login x,DocumentsDbContext db,IPasswordHasher<User> h)=>{var u=await db.Users.SingleOrDefaultAsync(y=>y.Username==x.Username);if(u==null||h.VerifyHashedPassword(u,u.PasswordHash,x.Password)==PasswordVerificationResult.Failed)return Results.Unauthorized();var cs=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.Role,u.Role)};var token=new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(claims:cs,expires:DateTime.UtcNow.AddHours(2),signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),SecurityAlgorithms.HmacSha256)));return Results.Ok(new{data=new{token,user=new{u.Id,u.Username,u.Role}}});});
app.MapGet("/api/documents",async(string? search,string? status,int page,int limit,ClaimsPrincipal u,DocumentsDbContext db)=>{page=Math.Max(1,page);limit=Math.Clamp(limit==0?20:limit,1,100);var q=db.Documents.AsNoTracking().Include(x=>x.Events).AsQueryable();if(u.IsInRole("User"))q=q.Where(x=>x.CreatedById==int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!));if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Title.Contains(search)||x.TrackingNumber.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);return Results.Ok(new{data=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*limit).Take(limit).ToListAsync(),pagination=new{page,limit,total=await q.CountAsync()}});}).RequireAuthorization();
app.MapPost("/api/documents",async(DocumentInput x,ClaimsPrincipal u,DocumentsDbContext db)=>{if(string.IsNullOrWhiteSpace(x.Title)||string.IsNullOrWhiteSpace(x.Department))return Results.BadRequest();var d=new TrackedDocument{TrackingNumber=$"DOC-{Guid.NewGuid().ToString("N")[..10].ToUpperInvariant()}",Title=x.Title.Trim(),Department=x.Department.Trim(),CreatedById=int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!)};db.Add(d);await db.SaveChangesAsync();return Results.Created($"/api/documents/{d.Id}",new{data=d});}).RequireAuthorization();
app.MapPatch("/api/documents/{id:int}/transition",async(int id,TransitionInput x,ClaimsPrincipal u,DocumentsDbContext db,DocumentService s)=>{var uid=int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);var d=await db.Documents.AsNoTracking().SingleOrDefaultAsync(y=>y.Id==id);if(d==null)return Results.NotFound();var reviewer=u.IsInRole("Admin")||u.IsInRole("Reviewer");if(!reviewer&&d.CreatedById!=uid)return Results.NotFound();try{return Results.Ok(new{data=await s.TransitionAsync(id,x.Status,x.Notes??"",uid,reviewer)});}catch(InvalidOperationException e){return Results.BadRequest(new{error=new{code="INVALID_TRANSITION",message=e.Message}});}catch(UnauthorizedAccessException){return Results.Forbid();}}).RequireAuthorization();
app.MapGet("/api/dashboard",async(DocumentsDbContext db)=>Results.Ok(new{data=await db.Documents.GroupBy(x=>x.Status).Select(g=>new{status=g.Key,total=g.Count()}).ToListAsync()})).RequireAuthorization(p=>p.RequireRole("Admin","Reviewer"));
await using(var scope=app.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<DocumentsDbContext>();await db.Database.EnsureCreatedAsync();if(!await db.Users.AnyAsync()){var h=scope.ServiceProvider.GetRequiredService<IPasswordHasher<User>>();foreach(var(n,r)in new[]{("admin","Admin"),("reviewer","Reviewer"),("user","User")}){var u=new User{Username=n,Role=r,PasswordHash="x"};u.PasswordHash=h.HashPassword(u,"ChangeMe123!");db.Add(u);}await db.SaveChangesAsync();}}
app.Run();public partial class Program;public sealed record Login(string Username,string Password);public sealed record DocumentInput(string Title,string Department);public sealed record TransitionInput(string Status,string? Notes);
